head.script:
///////// 1. 변수 및 선언 영역 /////////

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 상장처리현황 화면 진입점 — 현재 수행하는 초기화 로직 없음(구 초기화는 gform_onload 참조).
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 종료 시 처리 — 현재 수행하는 로직 없음.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageunload 바인딩으로 자동 호출)
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name MxDataSet_stat_OnLoadCompleted
 * @description 처리현황 데이터셋 로드 완료(구 콜백) — 총건수 영역(textbox_1)에 건수를 표시하고 로그 데이터셋을 초기화한다.
 * @param {Number} rowcount 조회 결과 행 수
 * @returns {void}
 * @hidden N
 * @example scwin.MxDataSet_stat_OnLoadCompleted(MxDataSet_stat.getRowCount());
 */
scwin.MxDataSet_stat_OnLoadCompleted = function(rowcount) {
    try {
        textbox_1.setValue("총 " + rowcount + "건");

        MxDataSet_log.removeAll();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10108.MxDataSet_stat_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name MxDataSet_log_OnLoadCompleted
 * @description 로그 데이터셋 로드 완료(구 콜백) — 처리현황 그리드(grid_stat)로 포커스를 되돌린다.
 * @param {Number} rowcount 조회 결과 행 수
 * @returns {void}
 * @hidden N
 * @example scwin.MxDataSet_log_OnLoadCompleted(MxDataSet_log.getRowCount());
 */
scwin.MxDataSet_log_OnLoadCompleted = function(rowcount) {
    try {
        grid_stat.Focus();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10108.MxDataSet_log_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_sys_search_onclick
 * @description [조회] 버튼 클릭 — 상장처리현황 목록을 조회한다(listSync).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_sys_search_onclick(e);
 */
scwin.btn_sys_search_onclick = function(e) {
    try {
        scwin.listSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10108.btn_sys_search_onclick" });
    }
};

/**
 * @method
 * @name btn_cal_onclick
 * @description 달력 버튼 클릭 — 기간 시작일(txb_date1) 선택 팝업 달력을 연다(popUpCalendar).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_cal_onclick(e);
 */
scwin.btn_cal_onclick = function(e) {
    try {
        popUpCalendar(txb_date_bg1, 'txb_date1', 'yyyymmdd'); // alert('image_2.onclick');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10108.btn_cal_onclick" });
    }
};

/**
 * @method
 * @name image_1_onclick
 * @description 달력 버튼 클릭 — 기간 종료일(txb_date2) 선택 팝업 달력을 연다(popUpCalendar).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.image_1_onclick(e);
 */
scwin.image_1_onclick = function(e) {
    try {
        popUpCalendar(txb_date_bg2, 'txb_date2', 'yyyymmdd'); // alert('image_2.onclick');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10108.image_1_onclick" });
    }
};

/**
 * @method
 * @name grid_stat_OnClick
 * @description 처리현황 그리드 행 클릭(구 콜백) — 선택 행의 업무처리번호(BZ_PROCS_NO)로 로그를 조회한다(logSync).
 * @param {Number} row 클릭한 행 인덱스
 * @param {String} colid 클릭한 컬럼 id
 * @returns {void}
 * @hidden N
 * @example scwin.grid_stat_OnClick(0, "BZ_PROCS_NO");
 */
scwin.grid_stat_OnClick = function(row, colid) {
    try {
        const sCd = MxDataSet_stat.getCellData(row, "BZ_PROCS_NO");
        scwin.logSync(sCd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10108.grid_stat_OnClick" });
    }
};

/**
 * @method
 * @name image_6_onclick
 * @description [발행회사검색] 버튼 클릭 — 발행회사 검색 팝업을 연다(isurcdSearch).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.image_6_onclick(e);
 */
scwin.image_6_onclick = function(e) {
    try {
        scwin.isurcdSearch(isur_cd, isur_nm);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT10108.image_6_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name code1Sync
 * @description 공통코드 조회 — /tbmccdval.do 를 동적 호출해 MxDataSet_code1~code3 을 순차 갱신한다.
 * @returns {void}
 * @hidden N
 * @example scwin.code1Sync();
 */
scwin.code1Sync = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_code1",
        action : "/tbmccdval.do",
        ref : "",
        target : "MxDataSet_code1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

    // ShowWin(MxGrid_1);
    const sbmOptions2 = {
        id : "sbm_MxDataSet_code2",
        action : "/tbmccdval.do",
        ref : "",
        target : "MxDataSet_code2=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);

    const sbmOptions3 = {
        id : "sbm_MxDataSet_code3",
        action : "/tbmccdval.do",
        ref : "",
        target : "MxDataSet_code3=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);

};

/**
 * @method
 * @name listSync
 * @description 상장처리현황 목록 조회 — 기간 입력 확인 후 업무구분/처리상태/시장구분/발행사/기간 조건으로 /listprocsstat.do 를 동적 호출, MxDataSet_stat 갱신 후 총건수 콜백을 연결한다.
 * @returns {void}
 * @hidden N
 * @example scwin.listSync();
 */
scwin.listSync = async function() {
    if (txb_date1.getValue() === "") {
        alert("시작일을 지정하여주십시요");
        return;
    }
    if (txb_date2.getValue() === "") {
        alert("종료일을 지정하여주십시요");
        return;
    }

    const cdCase1 = "&LIST_BZ_TP_CD=" + MxDataSet_code1.getCellData(MxCombo1.Index + 1, "CD_VAL");

    const cdCase2 = "&LIST_PROCS_STAT_CD=" + MxDataSet_code2.getCellData(MxCombo2.Index + 1, "CD_VAL");

    const cdCase3 = "&LD_MKT_TP_CD=" + MxDataSet_code3.getCellData(MxCombo3.Index + 1, "CD_VAL");
    const cdCase4 = "&ISUR_CD=" + ISUR_CD.getValue();
    const cdCase5 = "&DDTM_FROM=" + txb_date1.getValue() + "&DDTM_TO=" + txb_date2.getValue() + "&DDTM_CD=" + MxRadio.getValue();
    const sbmOptions = {
        id : "sbm_MxDataSet_stat",
        action : "/listprocsstat.do",
        ref : "",
        target : "MxDataSet_stat=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.MxDataSet_stat_OnLoadCompleted(MxDataSet_stat.getRowCount()); // 구 콜백 연결

};

/**
 * @method
 * @name logSync
 * @description 상장처리 로그 조회 — /listprocslog.do 를 동적 호출해 MxDataSet_log 를 갱신하고 완료 콜백을 연결한다.
 * @param {String} sval 업무처리번호(BZ_PROCS_NO)
 * @returns {void}
 * @hidden N
 * @example scwin.logSync(bzProcsNo);
 */
scwin.logSync = async function(sval) {
    const sbmOptions = {
        id : "sbm_MxDataSet_log",
        action : "/listprocslog.do",
        ref : "",
        target : "MxDataSet_log=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.MxDataSet_log_OnLoadCompleted(MxDataSet_log.getRowCount()); // 구 콜백 연결

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name gform_onload
 * @description 구 gform onload 초기화 — 기간구분 초기값 설정, 코드/현황/로그 데이터셋 초기 로드 후 공통코드·발행사 오토필 조회와 기간 기본값 설정을 수행한다.
 * @returns {void}
 * @hidden N
 * @example scwin.gform_onload();
 */
scwin.gform_onload = async function() {
    MxRadio.setValue(0);
    const sbmOptions = {
        id : "sbm_MxDataSet_code1",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_code1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

    const sbmOptions2 = {
        id : "sbm_MxDataSet_code2",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_code2=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);

    const sbmOptions3 = {
        id : "sbm_MxDataSet_code3",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_code3=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);

    const sbmOptions4 = {
        id : "sbm_MxDataSet_stat",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_stat=body.content",
        isProcessMsg : false
    };

    const sbmRtn4 = await $c.sbm.executeDynamic(sbmOptions4);
    scwin.MxDataSet_stat_OnLoadCompleted(MxDataSet_stat.getRowCount()); // 구 콜백 연결

    const sbmOptions5 = {
        id : "sbm_MxDataSet_log",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_log=body.content",
        isProcessMsg : false
    };

    const sbmRtn5 = await $c.sbm.executeDynamic(sbmOptions5);
    scwin.MxDataSet_log_OnLoadCompleted(MxDataSet_log.getRowCount()); // 구 콜백 연결

    scwin.code1Sync();
    await $c.cm.comIsur(isur_cd, isur_nm); // 발행사Autofill를 위한 스크립트

    toDaySet(txb_date1);

    toDaySet(txb_date2);
};

/**
 * @method
 * @name isurcdSearch
 * @description 발행회사검색 팝업(ULDCOM00007)을 열고 반환값("발행사코드^발행사명")을 대상 컴포넌트에 반영한다. pcc/stf $c.cm.isurcdSearch 는 팝업이 $c.cm.isurSearchRtn 을 되부르는 콜백 계약이라, 반환값 계약인 본 모듈 팝업과 맞지 않아 화면 로컬로 유지한다.
 * @param {Object} codeComp 발행사코드 컴포넌트(autoComplete)
 * @param {Object} labelComp 발행사명 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 * @example scwin.isurcdSearch(isur_cd, isur_nm);
 */
scwin.isurcdSearch = async function (codeComp, labelComp) {
    const options = { id : "ULDCOM00007", title : "발행회사검색창", type : "pageFramePopup", width : "618px", height : "730px" };
    const result = await $c.win.openPopup("/ui/common/ULDCOM00007.xml", options, {});
    if (result) {
        const [isurCd, comAbbrv] = String(result).split("^");
        codeComp.setValue(isurCd);
        labelComp.setValue(comAbbrv);
    }
};
